    {
        "role": "paragraph",
        "segment": "Two common values that can be calculated from E (the estimate) and A (the actual value) to assess accuracy are the absolute error and the relative error.",
        "citations": [],
        "type": null
    },
    {
        "role": "bullet_intro",
        "segment": "Two values and their meanings:",
        "citations": [],
        "type": null
    },
    {
        "role": "bullet",
        "segment": "Absolute error = |E − A|, which measures the magnitude of the difference between the estimate and the actual value without regard to direction. Smaller absolute error indicates a more accurate estimate.",
        "citations": [],
        "type": null
    },
    {
        "role": "bullet",
        "segment": "Relative error = |E − A| / |A| (or sometimes |E − A| / |E|), which expresses the error as a proportion of the true value or the estimate. It is useful for comparing errors across different scales. Smaller relative error indicates a more accurate estimate relative to the size of the value being estimated.",
        "citations": [],
        "type": null
    }
]

